// Tres servidores con relojes de pared desfasados. Cada uno registra un cambio de estado del despacho D-7.
const relojes = { deposito: +0, camion: -1800, oficina: -2500 }; // desfase en milisegundos respecto de la hora real
const horaReal = (t) => t; // el "tiempo verdadero" lo conocemos solo porque simulamos
const escrituras = [
  { quien: "deposito", real: 10000, valor: "cargado" },
  { quien: "camion",   real: 11000, valor: "en_ruta" },
  { quien: "oficina",  real: 12000, valor: "entregado" },
];
for (const e of escrituras) e.sello = e.real + relojes[e.quien];
console.log("Orden verdadero:   ", escrituras.map((e) => e.valor).join(" -> "));
const porSello = [...escrituras].sort((a, b) => a.sello - b.sello);
console.log("Orden por sello:   ", porSello.map((e) => `${e.valor}(${e.sello})`).join(" -> "));
console.log("Gana 'ultima escritura' (LWW):", porSello[porSello.length - 1].valor);

// Cálculo NTP (RFC 5905): T1 sale del cliente, T2 llega al servidor, T3 sale del servidor, T4 llega al cliente.
function ntp(T1, T2, T3, T4) {
  const theta = ((T2 - T1) + (T3 - T4)) / 2; // offset del servidor respecto del cliente
  const delta = (T4 - T1) - (T3 - T2);       // demora de ida y vuelta
  return { theta, delta };
}
// Caso 1: el cliente tiene el reloj 500 ms atrasado; camino simétrico de 20 ms de ida y 20 de vuelta; el servidor tarda 1 ms.
// Tiempo verdadero: sale a 1000, llega a 1020, el servidor responde a 1021, vuelve a 1041.
const atraso = -500;
let r = ntp(1000 + atraso, 1020, 1021, 1041 + atraso);
console.log("simétrico        ", r, "(el reloj del cliente está 500 ms atrasado: theta debe dar +500)");
// Caso 2: la ida tarda 80 ms y la vuelta 10 ms (ruta asimétrica). Mismo atraso.
r = ntp(1000 + atraso, 1080, 1081, 1091 + atraso);
console.log("asimétrico 80/10 ", r, "(error de theta = (ida - vuelta)/2 =", (80 - 10) / 2, "ms)");

// Relojes de Lamport en tres nodos. Mensajes con demora fija; ejecución determinista.
class Nodo {
  constructor(n) { this.n = n; this.c = 0; this.log = []; }
  evento(que) { this.c += 1; this.log.push({ c: this.c, n: this.n, que }); return this.c; }
  enviar(que) { const t = this.evento("envía " + que); return { t, de: this.n }; }
  recibir(msg, que) { this.c = Math.max(this.c, msg.t) + 1; this.log.push({ c: this.c, n: this.n, que: "recibe " + que + " (traía " + msg.t + ")" }); }
}
const dep = new Nodo("deposito"), cam = new Nodo("camion"), ofi = new Nodo("oficina");
dep.evento("carga el bulto");
dep.evento("imprime remito");
const m1 = dep.enviar("salida confirmada");       // deposito -> camion
cam.evento("arranca el GPS");                      // concurrente con lo del depósito
cam.recibir(m1, "salida confirmada");
cam.evento("sale a ruta");
const m2 = cam.enviar("en camino");                // camion -> oficina
ofi.evento("abre la planilla del día");            // concurrente
ofi.recibir(m2, "en camino");
ofi.evento("avisa al cliente");
const todo = [...dep.log, ...cam.log, ...ofi.log].sort((a, b) => a.c - b.c || (a.n < b.n ? -1 : 1));
for (const e of todo) console.log(String(e.c).padStart(2), e.n.padEnd(9), e.que);

// Relojes vectoriales: cada nodo lleva un contador por nodo.
const NODOS = ["A", "B", "C"];
const nuevo = () => ({ A: 0, B: 0, C: 0 });
const tic = (v, yo) => ({ ...v, [yo]: v[yo] + 1 });
const fusion = (a, b, yo) => { const r = {}; for (const k of NODOS) r[k] = Math.max(a[k], b[k]); return tic(r, yo); };
function comparar(a, b) {
  let menor = false, mayor = false;
  for (const k of NODOS) { if (a[k] < b[k]) menor = true; if (a[k] > b[k]) mayor = true; }
  if (!menor && !mayor) return "iguales";
  if (menor && !mayor) return "a → b (a pasó antes)";
  if (mayor && !menor) return "b → a (b pasó antes)";
  return "CONCURRENTES";
}
const f = (v) => `[${NODOS.map((k) => v[k]).join(",")}]`;
// A y B asignan el despacho D-7 a camiones distintos sin hablarse; C solo mira.
let A = nuevo(), B = nuevo(), C = nuevo();
A = tic(A, "A"); const asigA = A;           // A: "D-7 al camión 1"
B = tic(B, "B"); const asigB = B;           // B: "D-7 al camión 2"
console.log("A asigna:", f(asigA), " B asigna:", f(asigB), "=>", comparar(asigA, asigB));
// C recibe lo de A y después lo de B
C = fusion(C, asigA, "C"); console.log("C tras recibir A:", f(C));
C = fusion(C, asigB, "C"); console.log("C tras recibir B:", f(C));
// Ahora una versión posterior: A lee todo (por C) y corrige
let A2 = fusion(A, C, "A"); console.log("A corrige:", f(A2), "vs la de B:", comparar(asigB, A2));
